package com.consense.service.drafting;

import com.consense.common.JsonUtils;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static com.consense.service.drafting.DraftReviewGraph.*;

/** Pure source contracts; no model, product API, persistence or browser is used. */
class DraftKnownRootsTest {
    private static final String SHA=String.join("",Collections.nCopies(64,"a"));

    @Test void registeredCurrentInstructionRetainsAPendingBusinessCoreWithoutAModelResponse() {
        ObjectNode reading=excision("one");Map<String,Object> base=graph(reading);String before=JsonUtils.write(base);DraftKnownRoots.Result known=build(base,reading);
        assertEquals(1,known.roots().size());Map<String,Object> node=known.roots().get(0);assertEquals("worksSubjectToExcision",map(node.get("catalogAlignment")).get("baselineKey"));
        assertEquals("pending",node.get("status"));assertEquals(false,map(node.get("catalogAlignment")).get("confirmed"));assertEquals(false,map(node.get("definitionReview")).get("confirmed"));assertEquals(Collections.singletonList("one"),node.get("docIds"));assertEquals(note(),node.get("semanticSourceQuote"));
        assertTrue(list(node.get("editTargets")).isEmpty());assertTrue(map(node.get("correction")).isEmpty());assertFalse(node.containsKey("fixedValue"));assertFalse(JsonUtils.write(node).contains("historicalClause"));assertFalse(JsonUtils.write(node).contains("/current/"));assertEquals(before,JsonUtils.write(base));
        assertTrue(known.has(text(node.get("id"))));assertTrue(known.accepts(node));assertFalse(JsonUtils.write(known.descriptor()).contains(note()));assertEquals(64,text(known.descriptor().get(0).get("definitionSha256")).length());assertEquals("worksSubjectToExcision",known.descriptor().get(0).get("wireId"));assertEquals(node.get("id"),known.descriptor().get(0).get("id"));
        JsonNode anchor=JsonUtils.mapper().valueToTree(list(node.get("sourceAnchors")).get(0));assertEquals(1,anchor.path("sourceDocumentId").asInt());assertEquals("analysis-1",anchor.path("analysisRevision").asText());assertEquals(SHA,anchor.path("analysisInputSha256").asText());assertEquals(SHA,anchor.path("analysisSha256").asText());assertEquals(reading.path("guidanceNotes").path(0),anchor.path("sourceObservation"));assertEquals(reading.path("guidanceNotes").path(0).path("memberRanges"),anchor.path("observedRanges"));
    }
    @Test void fixedPrerequisitesRemainUnconfirmedInsteadOfBecomingAnUnconditionalInput() {
        ObjectNode reading=source("one","NTT",DraftBusinessRules.standardParagraph("NTT",172)+"\n"+DraftBusinessRules.standardParagraph("NTT",173),DraftBusinessRules.standardParagraph("NTT",166));Map<String,Object> base=graph(reading);DraftKnownRoots.Result known=build(base,reading);
        Map<String,Object> procedure=find(known,"twoEnvelopeTendering"),other=find(known,"otherTenderingArrangement"),format=find(known,"electronicTendering");
        assertEquals("choice",map(format.get("type")).get("kind"));assertEquals(new HashSet<>(Arrays.asList("L10Pro","Hardcopy")),optionValues(format));
        Map<String,Object> applicability=map(other.get("applicability"));assertEquals(false,applicability.get("confirmed"));assertEquals("all",applicability.get("mode"));assertEquals(procedure.get("id"),map(list(applicability.get("clauses")).get(0)).get("inputId"));assertEquals(false,map(list(applicability.get("clauses")).get(0)).get("value"));
        assertEquals("unknown",map(other.get("currentDefinitionReference")).get("conditionStatus"));state(base).put("variables",known.roots());Map<String,Object> evaluation=DraftReviewGraph.plan(base,Collections.emptyMap(),Collections.emptyMap(),false);assertEquals("unknown",map(evaluation.get("applicabilityStates")).get(other.get("id")));assertTrue(map(evaluation.get("effectiveValues")).isEmpty());
    }
    @Test void unmatchedAndUnboundInstructionsDoNotSeedKnownRoots() {
        ObjectNode changed=source("one","NTT",note()+" with a new condition",DraftBusinessRules.standardParagraph("NTT",243));assertTrue(build(graph(changed),changed).roots().isEmpty());
        ObjectNode stale=excision("one");((ObjectNode)stale.path("sourceMembers").path(0).path("sourcePosition")).put("sourceSha256","stale");assertTrue(build(graph(stale),stale).roots().isEmpty());
    }
    @Test void repeatedNotesShareOneUnconfirmedDefinitionWithoutCreatingAnEditingRange() {
        ObjectNode reading=excision("one"),duplicate=((ObjectNode)reading.path("guidanceNotes").path(0)).deepCopy();duplicate.put("id","second-note");reading.withArray("guidanceNotes").add(duplicate);DraftKnownRoots.Result known=build(graph(reading),reading);
        assertEquals(1,known.roots().size());Map<String,Object> root=known.roots().get(0);assertEquals("worksSubjectToExcision",map(root.get("currentDefinitionReference")).get("baselineKey"));assertEquals("pending",root.get("status"));assertTrue(list(root.get("editTargets")).isEmpty());assertEquals(false,map(root.get("currentDefinitionReference")).get("editableAuthority"));
    }
    @Test void unknownCurrentScopeDoesNotEraseAQuestionOrGrantAnEditingRange() {
        ObjectNode reading=excision("one");((ObjectNode)reading.path("groups").path(0)).put("scopeComplete",false);DraftKnownRoots.Result known=build(graph(reading),reading);assertEquals(1,known.roots().size());Map<String,Object> root=known.roots().get(0);assertTrue(list(root.get("editTargets")).isEmpty());assertEquals("unknown",map(root.get("currentDefinitionReference")).get("conditionStatus"));assertEquals("pending",root.get("status"));assertEquals(false,map(root.get("definitionReview")).get("confirmed"));assertEquals(false,map(root.get("currentDefinitionReference")).get("editableAuthority"));
    }
    @Test void anUnmatchedTargetKeepsOnlyTheSharedBusinessDefinitionFromTheExactNote() {
        ObjectNode reading=source("one","NTT",DraftBusinessRules.standardParagraph("NTT",135),"The altered clause governs another object.");DraftKnownRoots.Result known=build(graph(reading),reading);assertEquals(1,known.roots().size());Map<String,Object> root=known.roots().get(0);
        assertEquals("electronicTendering",map(root.get("currentDefinitionReference")).get("baselineKey"));assertEquals("pending",root.get("status"));assertTrue(list(root.get("editTargets")).isEmpty());assertTrue(map(root.get("correction")).isEmpty());assertEquals(false,map(root.get("currentDefinitionReference")).get("editableAuthority"));
    }
    @Test void theCurrentWtoNoteSuppliesItsFixedBusinessDefinitionWithoutProjectAnswers(){
        ObjectNode reading=source("one","NTT",DraftBusinessRules.standardParagraph("NTT",439),"Current target still requires source review.");DraftKnownRoots.Result known=build(graph(reading),reading);assertEquals(1,known.roots().size());Map<String,Object> root=known.roots().get(0);String task=text(DraftReviewDiscovery.sourceTasks(Collections.singletonList(reading)).get(0).get("taskId"));
        assertEquals(Collections.singleton("wtoGpaApplies"),known.forTasks(Collections.singletonList(task)).keySet());assertEquals("pending",root.get("status"));assertFalse(root.containsKey("fixedValue"));assertTrue(list(root.get("editTargets")).isEmpty());assertEquals(false,map(root.get("currentDefinitionReference")).get("editableAuthority"));
    }
    @Test void theExplicitIncompleteRailwayDefinitionRetainsItsOriginalSourceFlagsAndRanges(){
        ObjectNode reading=incompleteRailway();String before=reading.toString();Map<String,Object> task=DraftReviewDiscovery.sourceTasks(Collections.singletonList(reading)).get(0);assertNull(DraftReviewDiscovery.sourceTaskAnchor(reading,task));Map<String,Object> anchor=DraftReviewDiscovery.registeredIncompleteInstructionAnchor(reading,task);assertNotNull(anchor);JsonNode original=JsonUtils.mapper().valueToTree(anchor.get("sourceObservation"));assertFalse(original.path("captureComplete").asBoolean());assertFalse(original.path("sourceSyntaxComplete").asBoolean());assertEquals(reading.path("guidanceNotes").path(0),original);
        DraftKnownRoots.Result known=build(graph(reading),reading);assertEquals(1,known.roots().size());Map<String,Object> root=known.roots().get(0);assertEquals("railwayProtectionAreaWorks",map(root.get("currentDefinitionReference")).get("baselineKey"));assertEquals("pending",root.get("status"));assertTrue(list(root.get("editTargets")).isEmpty());assertEquals(false,map(root.get("currentDefinitionReference")).get("editableAuthority"));assertEquals(before,reading.toString());
        Map<String,Object> wrongTask=new LinkedHashMap<>(task);wrongTask.put("sourceSha256","another-source");assertNull(DraftReviewDiscovery.registeredIncompleteInstructionAnchor(reading,wrongTask));
    }
    @Test void anIncompleteRegistrationCannotBypassMissingSourceOrDifferentMeaning(){
        for(String defect:Arrays.asList("changed-text","syntax-unknown","missing-capture","missing-syntax","wrong-family","stale-member","missing-analysis","missing-range","duplicate-note")){
            ObjectNode reading=incompleteRailway(),note=(ObjectNode)reading.path("guidanceNotes").path(0);
            if("changed-text".equals(defect))note.put("text",note.path("text").asText().replace("no part of the","any part of the"));if("syntax-unknown".equals(defect))note.put("sourceSyntaxKnown",false);if("missing-capture".equals(defect))note.remove("captureComplete");if("missing-syntax".equals(defect))note.remove("sourceSyntaxComplete");if("wrong-family".equals(defect))reading.put("fileKey","SCT");if("stale-member".equals(defect))((ObjectNode)reading.path("sourceMembers").path(2).path("sourcePosition")).put("sourceSha256","stale");if("missing-analysis".equals(defect))reading.remove("analysisSha256");if("missing-range".equals(defect))note.remove("memberRanges");if("duplicate-note".equals(defect))reading.withArray("guidanceNotes").add(note.deepCopy());assertTrue(build(graph(reading),reading).roots().isEmpty(),defect);
        }
        ObjectNode other=source("one","NTT",DraftBusinessRules.standardParagraph("NTT",439),"Unknown scope");((ObjectNode)other.path("guidanceNotes").path(0)).put("captureComplete",false).put("sourceSyntaxKnown",true).put("sourceSyntaxComplete",false);assertTrue(build(graph(other),other).roots().isEmpty(),"The exception must not cover other registered notes");
    }
    @Test void missingCurrentObservationRangesOrAnalysisCannotBecomeAWeakSourceAnchor() {
        for(String missing:Arrays.asList("sourceDocumentId","analysisRevision","analysisInputSha256","analysisSha256","memberRanges")){
            ObjectNode reading=excision("one");if("memberRanges".equals(missing))((ObjectNode)reading.path("guidanceNotes").path(0)).remove(missing);else reading.remove(missing);assertTrue(build(graph(reading),reading).roots().isEmpty(),missing);
        }
    }
    @Test void theSameKnownRootIsSharedButEachGroupGetsOnlyItsOwnPrimaryTaskAuthority() {
        ObjectNode first=excision("one"),second=excision("two");Map<String,Object> base=graph(first,second);map(base.get("selectedDocuments")).clear();DraftKnownRoots.Result known=build(base,first,second);assertEquals(1,known.roots().size());
        String firstTask=text(DraftReviewDiscovery.sourceTasks(Collections.singletonList(first)).get(0).get("taskId")),secondTask=text(DraftReviewDiscovery.sourceTasks(Collections.singletonList(second)).get(0).get("taskId"));Map<String,Map<String,Object>> one=known.forTasks(Collections.singletonList(firstTask)),two=known.forTasks(Collections.singletonList(secondTask));assertEquals(one.keySet(),two.keySet());assertEquals(Collections.singleton("worksSubjectToExcision"),one.keySet());
        Map<String,Object> reference=map(one.get("worksSubjectToExcision").get("currentDefinitionReference"));assertEquals(Collections.singletonList(firstTask),reference.get("taskIds"));assertEquals(Collections.singleton(firstTask),map(reference.get("taskQuotes")).keySet());assertTrue(known.forTasks(Collections.singletonList("not-a-current-task")).isEmpty());
    }
    @Test void anotherTaskOnTheSameCurrentSourceCanReferenceButCannotPatchTheKnownRoot() {
        ObjectNode reading=excision("one");String extra="A different unregistered current instruction.";ObjectNode note=reading.withArray("guidanceNotes").addObject().put("id","extra-note").put("text",extra).put("captureComplete",true);note.putArray("orderedMemberIds").add("extra-member");note.putArray("memberRanges").addObject().put("memberId","extra-member").put("channel","text").put("start",0).put("end",extra.length());member(reading,"extra-member",extra);
        ObjectNode other=source("two","NTT",extra,"Other source scope");Map<String,Object> base=graph(reading,other);map(base.get("selectedDocuments")).put("NTT","one");DraftKnownRoots.Result known=build(base,reading,other);String extraTask="";for(Map<String,Object> task:DraftReviewDiscovery.sourceTasks(Collections.singletonList(reading)))if("extra-note".equals(task.get("sourceObservationId")))extraTask=text(task.get("taskId"));assertFalse(extraTask.isEmpty());Map<String,Map<String,Object>> visible=known.forTasks(Collections.singletonList(extraTask));assertEquals(1,visible.size());Map<String,Object> reference=map(visible.values().iterator().next().get("currentDefinitionReference"));assertTrue(list(reference.get("taskIds")).isEmpty());assertTrue(map(reference.get("taskQuotes")).isEmpty());String foreignTask=text(DraftReviewDiscovery.sourceTasks(Collections.singletonList(other)).get(0).get("taskId"));assertTrue(known.forTasks(Collections.singletonList(foreignTask)).isEmpty());
    }
    @Test void anExplicitDocumentSelectionRestrictsProofsAndAliasesToThatSource() {
        for(String fileKey:Arrays.asList("NTT","SCC")) {
            ObjectNode selected="SCC".equals(fileKey)?scc("selected"):excision("selected"),other="SCC".equals(fileKey)?scc("other"):excision("other");Map<String,Object> base=graph(selected,other);map(base.get("selectedDocuments")).put(fileKey,"selected");DraftKnownRoots.Result known=build(base,selected,other);assertFalse(known.roots().isEmpty(),fileKey);
            for(Map<String,Object> node:known.roots()){assertEquals(Collections.singletonList("selected"),node.get("docIds"));for(Object reference:list(map(node.get("currentDefinitionReference")).get("sourceReferences")))assertEquals("selected",map(reference).get("sourceId"));}
            String foreignTask=text(DraftReviewDiscovery.sourceTasks(Collections.singletonList(other)).get(0).get("taskId"));assertTrue(known.forTasks(Collections.singletonList(foreignTask)).isEmpty());
            map(base.get("selectedDocuments")).put(fileKey,"missing-source");assertTrue(build(base,selected,other).roots().isEmpty(),fileKey);
        }
    }
    @Test void multipleSccSourcesWithoutASelectionDoNotSeedSccButOtherDocumentsContinue() {
        ObjectNode first=scc("scc-one"),second=scc("scc-two"),ntt=excision("ntt");Map<String,Object> base=graph(first,second,ntt);map(base.get("selectedDocuments")).remove("SCC");DraftKnownRoots.Result known=build(base,first,second,ntt);assertEquals(1,known.roots().size());assertEquals("worksSubjectToExcision",map(known.roots().get(0).get("catalogAlignment")).get("baselineKey"));assertEquals(Collections.singletonList("ntt"),known.roots().get(0).get("docIds"));
        for(ObjectNode reading:Arrays.asList(first,second)){String task=text(DraftReviewDiscovery.sourceTasks(Collections.singletonList(reading)).get(0).get("taskId"));assertTrue(known.forTasks(Collections.singletonList(task)).isEmpty());}
        Map<String,Object> single=graph(first);map(single.get("selectedDocuments")).clear();assertFalse(build(single,first).roots().isEmpty());
    }
    @Test void modelRulesCanExtendAKnownCoreButCannotRenameOrReconfirmIt() {
        ObjectNode reading=excision("one");DraftKnownRoots.Result known=build(graph(reading),reading);Map<String,Object> rule=known.roots().get(0);rule.put("sourceTaskId","current-task");rule.put("modelLocalId","worksSubjectToExcision");rule.put("correction",obj("branches",Collections.emptyList()));rule.put("editTargets",Collections.singletonList(obj("action","check")));rule.put("relatedInputIds",Collections.singletonList("another-known-root"));rule.put("sourceAnchors",Collections.emptyList());rule.put("docIds",Arrays.asList("one","two"));assertTrue(known.accepts(rule));
        for(String field:Arrays.asList("questionEn","nameEn","status","definitionKind")){Map<String,Object> changed=copy(rule);changed.put(field,"changed");assertFalse(known.accepts(changed),field);}
        Map<String,Object> confirmed=copy(rule);map(confirmed.get("catalogAlignment")).put("confirmed",true);assertFalse(known.accepts(confirmed));Map<String,Object> wrongRole=copy(rule);wrongRole.put("role",obj("kind","derived"));assertFalse(known.accepts(wrongRole));
    }
    @Test void anExistingCompatibleHumanDefinitionIsReusedWithoutOverwritingItsCore() {
        ObjectNode reading=excision("one");Map<String,Object> base=graph(reading),existing=build(base,reading).roots().get(0);existing.put("id","human-root");existing.put("nameEn","Human reviewed name");existing.put("questionEn","Human reviewed question");existing.put("manual",true);existing.put("status","confirmed");map(existing.get("catalogAlignment")).put("confirmed",true);map(existing.get("catalogAlignment")).put("reason","Human checked this definition.");state(base).put("variables",Collections.singletonList(existing));String before=JsonUtils.write(base);
        DraftKnownRoots.Result known=build(base,reading);Map<String,Object> retained=known.roots().get(0);assertEquals("human-root",retained.get("id"));assertEquals("Human reviewed name",retained.get("nameEn"));assertEquals("Human reviewed question",retained.get("questionEn"));assertEquals(true,retained.get("manual"));assertEquals("confirmed",retained.get("status"));assertEquals(true,map(retained.get("currentDefinitionReference")).get("existing"));assertEquals(before,JsonUtils.write(base));
    }
    @Test void excludedIncompatibleOrAmbiguousHumanRootsAreNotReplaced() {
        ObjectNode reading=excision("one");Map<String,Object> empty=graph(reading),original=build(empty,reading).roots().get(0);
        for(String problem:Arrays.asList("excluded","incompatible","ambiguous","catalog-excluded")){Map<String,Object> base=graph(reading),existing=copy(original);existing.put("id","human-root");if("excluded".equals(problem))existing.put("status","excluded");if("incompatible".equals(problem))existing.put("type",obj("kind","text"));List<Object> variables=new ArrayList<>();variables.add(existing);if("ambiguous".equals(problem)){Map<String,Object> duplicate=copy(existing);duplicate.put("id","another-human-root");variables.add(duplicate);}state(base).put("variables",variables);if("catalog-excluded".equals(problem))state(base).put("catalogReview",obj("exclusions",obj("worksSubjectToExcision",obj("reason","Excluded for this project"))));String before=JsonUtils.write(base);assertTrue(build(base,reading).roots().isEmpty(),problem);assertEquals(before,JsonUtils.write(base));}
    }
    @Test void callerChangesCannotMutateThePlanDefinitionOrItsFingerprint() {
        ObjectNode reading=excision("one");DraftKnownRoots.Result known=build(graph(reading),reading);String original=JsonUtils.write(known.roots()),descriptor=JsonUtils.write(known.descriptor());known.roots().get(0).put("nameEn","changed");map(list(known.descriptor().get(0).get("sourceReferences")).get(0)).put("sourceId","changed");assertEquals(original,JsonUtils.write(known.roots()));assertEquals(descriptor,JsonUtils.write(known.descriptor()));
    }
    private static DraftKnownRoots.Result build(Map<String,Object> base,ObjectNode... readings) {
        Map<String,JsonNode> byId=new LinkedHashMap<>();for(ObjectNode reading:readings)byId.put(reading.path("id").asText(),reading);List<JsonNode> sources=new ArrayList<>(byId.values());return DraftKnownRoots.build(byId,DraftReviewDiscovery.sourceTasks(sources),DraftDiscoveryGroups.currentTemplateIndexes(byId),base);
    }
    private static Map<String,Object> find(DraftKnownRoots.Result result,String key){for(Map<String,Object> node:result.roots())if(key.equals(map(node.get("catalogAlignment")).get("baselineKey")))return node;throw new AssertionError("Missing known root: "+key);}
    private static Set<Object> optionValues(Map<String,Object> node){Set<Object> values=new HashSet<>();for(Object option:list(node.get("options")))values.add(map(option).get("value"));return values;}
    private static Map<String,Object> graph(ObjectNode... readings){List<Object> sources=new ArrayList<>();Map<String,Object> selection=new LinkedHashMap<>();for(ObjectNode reading:readings){sources.add(obj("id",reading.path("id").asText(),"fileKey",reading.path("fileKey").asText(),"sourceSha256",SHA,"evidenceStatus","bound","format","docx"));selection.put(reading.path("fileKey").asText(),reading.path("id").asText());}return obj("sources",sources,"selectedDocuments",selection,"graph",obj("variables",new ArrayList<>(),"events",new ArrayList<>()));}
    private static ObjectNode excision(String id){return source(id,"NTT",note(),DraftBusinessRules.standardParagraph("NTT",243));}
    private static ObjectNode incompleteRailway(){String[] pieces={DraftBusinessRules.standardParagraph("NTT",614),DraftBusinessRules.standardParagraph("NTT",617),DraftBusinessRules.standardParagraph("NTT",620),""};ObjectNode reading=source("one","NTT",String.join("\n",pieces),DraftBusinessRules.standardParagraph("NTT",619)),note=(ObjectNode)reading.path("guidanceNotes").path(0);note.put("captureComplete",false).put("sourceSyntaxKnown",true).put("sourceSyntaxComplete",false);note.putObject("endBoundary").put("kind","unclosed_or_unobserved_continuation").put("memberId","railway-note-3");note.putArray("memberRanges");note.putArray("orderedMemberIds");for(int index=0;index<pieces.length;index++){String id="railway-note-"+index;member(reading,id,pieces[index]);note.withArray("orderedMemberIds").add(id);note.withArray("memberRanges").addObject().put("memberId",id).put("channel","text").put("start",0).put("end",pieces[index].length());}return reading;}
    private static ObjectNode scc(String id){return source(id,"SCC",DraftBusinessRules.standardParagraph("SCC",100),DraftBusinessRules.standardParagraph("SCC",108));}
    private static String note(){return DraftBusinessRules.standardParagraph("NTT",244);}
    private static ObjectNode source(String id,String document,String note,String body){ObjectNode reading=JsonUtils.mapper().createObjectNode().put("id",id).put("sourceDocumentId",1).put("fileKey",document).put("sourceSha256",SHA).put("evidenceStatus","bound").put("format","docx").put("analysisRevision","analysis-1").put("analysisInputSha256",SHA).put("analysisSha256",SHA);ObjectNode guidance=reading.putArray("guidanceNotes").addObject().put("id","note").put("text",note).put("captureComplete",true);guidance.putArray("orderedMemberIds").add("note-member");guidance.putArray("memberRanges").addObject().put("memberId","note-member").put("channel","text").put("start",0).put("end",note.length());ObjectNode scope=reading.putArray("groups").addObject().put("id","scope").put("text",body).put("scopeComplete",true);scope.putArray("guidanceNoteIds").add("note");scope.putArray("memberRanges").addObject().put("memberId","body-member").put("channel","text").put("start",0).put("end",body.length());reading.putArray("sourceMembers");member(reading,"note-member",note);member(reading,"body-member",body);return reading;}
    private static void member(ObjectNode reading,String id,String text){ObjectNode member=reading.withArray("sourceMembers").addObject().put("id",id);member.putObject("textObservation").put("text",text);member.putObject("sourcePosition").put("sourceSha256",SHA).put("partName","word/document.xml").put("nodePath","/current/"+id);}
    private static Map<String,Object> copy(Map<String,Object> node){return JsonUtils.readMap(JsonUtils.write(node));}
}
